 */
function addInboxItem(text: string): string {
  const result = kspecJson<{ item: { _ulid: string } }>(
    `inbox add "${text}"`,
    tempDir,
  );
  return result.item._ulid;
}

/**
 * Helper: create a triage record for an inbox item
 */
function triageItem(
  inboxUlid: string,
  action: string,
  reasoning: string,
): void {
