  title: string;
  completed_at: string;
  closed_reason: string | null;
  origin?: "manual" | "derived" | "observation_promotion";
}

export interface CommitSummary {
  hash: string;
  full_hash: string;
  date: string;
  message: string;
  author: string;
  task_refs: string[];
}

/**
 * A single entry in the unified activity timeline.
 * Merges completed tasks and git commits into a chronological view.
 * Commits linked to tasks via Task: @slug trailer are deduplicated into combined entries.
 */
export type ActivityItem =
  | { type: "task_completion"; date: string; task: CompletedTaskSummary }
  | { type: "commit"; date: string; commit: CommitSummary }
  | {
      type: "linked_commit";
      date: string;
      commit: CommitSummary;
      task: CompletedTaskSummary;
    };

export interface SessionStats {
  total_tasks: number;
  in_progress: number;
  needs_work: number;
  pending_review: number;
  ready: number;
  blocked: number;
  completed: number;
  inbox_items: number;
}

export interface InboxSummary {
  ref: string;
  text: string;
  created_at: string;
  tags: string[];
  added_by: string | null;
  triaged: boolean;
  triage_action: string | null;
}

export interface InboxStats {
  total: number;
  untriaged: number;
  deferred: number;
  triaged: number;
}

export interface SessionOptions {
  brief?: boolean;
  full?: boolean;
  since?: string;
  git?: boolean;
  limit?: string;
  eligible?: boolean; // Only include automation-eligible tasks in ready_tasks
}

// ─── Data Gathering ──────────────────────────────────────────────────────────

/**
 * Build a reverse dependency map: for each task ULID, count how many
 * pending tasks depend on it. Unresolvable refs are silently skipped.
 */
function computeUnlocksMap(
  allTasks: LoadedTask[],
  index: ReferenceIndex,
): Map<string, number> {
  const counts = new Map<string, number>();

  for (const task of allTasks) {
    // Only count pending tasks as "unlockable" downstream work per spec
    if (task.status !== "pending") continue;

    for (const depRef of task.depends_on) {
      const result = index.resolve(depRef);
      if (!result.ok) continue; // AC: unresolvable refs silently skipped
      const depUlid = result.item._ulid;
      counts.set(depUlid, (counts.get(depUlid) || 0) + 1);
    }
  }

  return counts;
}

function toActiveTaskSummary(
  task: LoadedTask,
  index: ReferenceIndex,
): ActiveTaskSummary {
  const lastNote =
    task.notes.length > 0 ? task.notes[task.notes.length - 1] : null;
  const incompleteTodos = task.todos.filter((t) => !t.done).length;
  return {
    ref: index.shortUlid(task._ulid),
    title: task.title,
    started_at: task.started_at || null,
    priority: task.priority,
    spec_ref: task.spec_ref || null,
    note_count: task.notes.length,
    last_note_at: lastNote ? lastNote.created_at : null,
    todo_count: task.todos.length,
    incomplete_todos: incompleteTodos,
  };
}

function toReadyTaskSummary(
  task: LoadedTask,
  index: ReferenceIndex,
  unlocksMap: Map<string, number>,
): ReadyTaskSummary {
  return {
    ref: index.shortUlid(task._ulid),
    title: task.title,
    priority: task.priority,
    spec_ref: task.spec_ref || null,
    tags: task.tags,
    unlocks: unlocksMap.get(task._ulid) || 0,
  };
}

function toBlockedTaskSummary(
  task: LoadedTask,
  _allTasks: LoadedTask[],
  index: ReferenceIndex,
  unlocksMap: Map<string, number>,
): BlockedTaskSummary {
  // Find unmet dependencies
  const unmetDeps: string[] = [];
  for (const depRef of task.depends_on) {
    const result = index.resolve(depRef);
    if (result.ok) {
      const depItem = result.item;
      if ("status" in depItem && depItem.status !== "completed") {
        unmetDeps.push(depRef);
      }
    }
  }

  return {
    ref: index.shortUlid(task._ulid),
    title: task.title,
    blocked_by: task.blocked_by,
    unmet_deps: unmetDeps,
    unlocks: unlocksMap.get(task._ulid) || 0,
  };
}

function toCompletedTaskSummary(
  task: LoadedTask,
  index: ReferenceIndex,
): CompletedTaskSummary {
  return {
    ref: index.shortUlid(task._ulid),
    title: task.title,
    completed_at: task.completed_at || "",
    closed_reason: task.closed_reason || null,
    origin: task.origin,
  };
}

