export interface SessionContext {
  /** When this context was generated */
  generated_at: string;

  /** Current git branch */
  branch: string | null;

  /** Session context (focus, threads, questions) */
  context: StoredSessionContext | null;

  /** Tasks currently in progress */
  active_tasks: ActiveTaskSummary[];

  /** Tasks awaiting review (code done, PR pending) */
  pending_review_tasks: ActiveTaskSummary[];

  /** Recent notes from active tasks */
  recent_notes: NoteSummary[];

  /** Incomplete todos from active tasks */
  active_todos: TodoSummary[];

  /** Tasks ready to be picked up */
  ready_tasks: ReadyTaskSummary[];

  /** Blocked tasks with blockers */
  blocked_tasks: BlockedTaskSummary[];

  /** Recently completed tasks */
  recently_completed: CompletedTaskSummary[];

  /** Recent git commits */
  recent_commits: CommitSummary[];

  /** Unified activity timeline (merged tasks + commits, deduplicated) */
  activity_timeline: ActivityItem[];

  /** Working tree status */
  working_tree: GitWorkingTree | null;

  /** Inbox items awaiting triage (oldest first) */
  inbox_items: InboxSummary[];

  /** Inbox triage statistics */
  inbox_stats: InboxStats;

  /** Summary statistics */
  stats: SessionStats;
}

export interface ActiveTaskSummary {
  ref: string;
  title: string;
  started_at: string | null;
  priority: number;
  spec_ref: string | null;
  note_count: number;
  last_note_at: string | null;
  todo_count: number;
  incomplete_todos: number;
}

export interface NoteSummary {
  task_ref: string;
  task_title: string;
  task_status: "in_progress" | "pending_review" | "needs_work" | "completed";
  note_ulid: string;
  created_at: string;
  author: string | null;
  content: string;
}

export interface TodoSummary {
  task_ref: string;
  task_title: string;
  id: number;
  text: string;
  added_at: string;
  added_by: string | null;
}

export interface ReadyTaskSummary {
  ref: string;
  title: string;
  priority: number;
  spec_ref: string | null;
  tags: string[];
  unlocks: number;
}

export interface BlockedTaskSummary {
  ref: string;
  title: string;
  blocked_by: string[];
  unmet_deps: string[];
  unlocks: number;
}

export interface CompletedTaskSummary {
  ref: string;
  title: string;
  completed_at: string;
  closed_reason: string | null;
  origin?: "manual" | "derived" | "observation_promotion";
}

export interface CommitSummary {
  hash: string;
  full_hash: string;
  date: string;
  message: string;
  author: string;
  task_refs: string[];
}

/**
 * A single entry in the unified activity timeline.
 * Merges completed tasks and git commits into a chronological view.
 * Commits linked to tasks via Task: @slug trailer are deduplicated into combined entries.
 */
export type ActivityItem =
  | { type: "task_completion"; date: string; task: CompletedTaskSummary }
  | { type: "commit"; date: string; commit: CommitSummary }
  | {
      type: "linked_commit";
      date: string;
      commit: CommitSummary;
      task: CompletedTaskSummary;
    };

export interface SessionStats {
  total_tasks: number;
  in_progress: number;
  needs_work: number;
  pending_review: number;
  ready: number;
  blocked: number;
  completed: number;
  inbox_items: number;
}

export interface InboxSummary {
  ref: string;
  text: string;
  created_at: string;
  tags: string[];
  added_by: string | null;
  triaged: boolean;
  triage_action: string | null;
}

export interface InboxStats {
  total: number;
  untriaged: number;
  deferred: number;
  triaged: number;
}

export interface SessionOptions {
  brief?: boolean;
  full?: boolean;
  since?: string;
  git?: boolean;
  limit?: string;
  eligible?: boolean; // Only include automation-eligible tasks in ready_tasks
}

// ─── Data Gathering ──────────────────────────────────────────────────────────

/**
 * Build a reverse dependency map: for each task ULID, count how many
 * pending tasks depend on it. Unresolvable refs are silently skipped.
 */
function computeUnlocksMap(
  allTasks: LoadedTask[],
  index: ReferenceIndex,
): Map<string, number> {
  const counts = new Map<string, number>();

  for (const task of allTasks) {
    // Only count pending tasks as "unlockable" downstream work per spec
    if (task.status !== "pending") continue;

    for (const depRef of task.depends_on) {
      const result = index.resolve(depRef);
      if (!result.ok) continue; // AC: unresolvable refs silently skipped
      const depUlid = result.item._ulid;
      counts.set(depUlid, (counts.get(depUlid) || 0) + 1);
    }
  }

  return counts;
}

function toActiveTaskSummary(
  task: LoadedTask,
  index: ReferenceIndex,
): ActiveTaskSummary {
  const lastNote =
    task.notes.length > 0 ? task.notes[task.notes.length - 1] : null;

