  // AC: @cmd-session-start ac-json-raw-preserved
  describe('JSON raw arrays preserved', () => {
    it('should include recently_completed array in JSON', { timeout: 20000 }, () => {
      kspec('task add --title "Task A" --slug task-a', tempDir);
