   593→    .filter((t) => !options.eligible || t.automation === "eligible")
   594→    .sort((a, b) => a.priority - b.priority)
   595→    .slice(0, options.full ? undefined : limit)
   596→    .map((t) => toActiveTaskSummary(t, index));
   597→
   598→  // Get pending review tasks
   599→  const pendingReviewTasks = allTasks
   600→    .filter((t) => t.status === "pending_review")
   601→    .sort((a, b) => a.priority - b.priority)
   602→    .slice(0, options.full ? undefined : limit)
   603→    .map((t) => toActiveTaskSummary(t, index));
   604→
   605→  // Get recent notes from active, pending_review, and recently completed tasks
   606→  // AC: @cmd-session-start ac-1, ac-2
   607→  // Collect notes per-status first to prevent one status from starving others
   608→  const noteLimitPerStatus = options.full ? limit : Math.ceil(limit / 3);
   609→
   610→  const inProgressNotes = collectRecentNotes(
   611→    allTasks.filter((t) => t.status === "in_progress" || t.status === "needs_work"),
   612→    index,
   613→    { limit: noteLimitPerStatus, since: sinceDate },
   614→  );
   615→
   616→  const pendingReviewNotes = collectRecentNotes(
   617→    allTasks.filter((t) => t.status === "pending_review"),
   618→    index,
   619→    { limit: noteLimitPerStatus, since: sinceDate },
   620→  );
   621→
   622→  const recentlyCompletedForNotes = allTasks
   623→    .filter((t) => t.status === "completed" && t.completed_at)
   624→    .sort((a, b) => {
   625→      const aDate = new Date(a.completed_at || 0);
   626→      const bDate = new Date(b.completed_at || 0);
   627→      return bDate.getTime() - aDate.getTime();
   628→    })
   629→    .slice(0, 5); // Last 3-5 completed tasks per AC-2
   630→
   631→  const completedNotes = collectRecentNotes(
   632→    recentlyCompletedForNotes,
   633→    index,
   634→    { limit: noteLimitPerStatus, since: sinceDate },
   635→  );
   636→
   637→  // Combine notes from all statuses, preserving representation from each
   638→  const recentNotes = [...inProgressNotes, ...pendingReviewNotes, ...completedNotes]
   639→    .sort(
   640→      (a, b) =>
   641→        new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
   642→    );
   643→
   644→  // Get incomplete todos from active tasks
   645→  const activeTodos = collectIncompleteTodos(
   646→    allTasks.filter((t) => t.status === "in_progress" || t.status === "needs_work"),
   647→    index,
   648→    { limit: options.full ? limit * 2 : limit },
   649→  );
   650→
   651→  // Compute reverse dependency map for "unlocks N" annotations
   652→  const unlocksMap = computeUnlocksMap(allTasks, index);
   653→
   654→  // AC: @cmd-session-start ac-primer-default, ac-full-sections
   655→  // Primer: top 5 ready tasks; Full: all ready tasks
   656→  const readyLimit = options.full ? undefined : 5;
   657→  const readyTasks = getReadyTasks(allTasks)
   658→    .filter((t) => !options.eligible || t.automation === "eligible")
   659→    .slice(0, readyLimit)
   660→    .map((t) => toReadyTaskSummary(t, index, unlocksMap));
   661→
   662→  // Get blocked tasks
   663→  const blockedTasks = allTasks
   664→    .filter((t) => t.status === "blocked")
   665→    .slice(0, options.full ? undefined : limit)
   666→    .map((t) => toBlockedTaskSummary(t, allTasks, index, unlocksMap));
   667→
   668→  // Get recently completed tasks
   669→  const recentlyCompleted = allTasks
   670→    .filter((t) => {
   671→      if (t.status !== "completed" || !t.completed_at) return false;
   672→      const completedDate = new Date(t.completed_at);
   673→      if (sinceDate && completedDate < sinceDate) return false;
   674→      return true;
   675→    })
   676→    .sort((a, b) => {
   677→      // Sort by completed_at descending (most recent first)
   678→      const aDate = new Date(a.completed_at || 0);
   679→      const bDate = new Date(b.completed_at || 0);
   680→      return bDate.getTime() - aDate.getTime();
   681→    })
   682→    .slice(0, options.full ? undefined : limit)
   683→    .map((t) => toCompletedTaskSummary(t, index));
   684→
   685→  // Get git info
   686→  let branch: string | null = null;
   687→  let recentCommits: CommitSummary[] = [];
   688→  let workingTree: GitWorkingTree | null = null;
   689→
   690→  if (showGit && isGitRepo(ctx.rootDir)) {
   691→    branch = getCurrentBranch(ctx.rootDir);
   692→
   693→    const commits = getRecentCommits({
   694→      limit: options.full ? limit * 2 : limit,
   695→      since: sinceDate || undefined,
   696→      cwd: ctx.rootDir,
   697→    });
   698→
   699→    recentCommits = commits.map((c) => ({
   700→      hash: c.hash,
   701→      full_hash: c.fullHash,
   702→      date: c.date.toISOString(),
   703→      message: c.message,
   704→      author: c.author,
   705→      task_refs: c.taskRefs,
   706→    }));
   707→
   708→    workingTree = getWorkingTreeStatus(ctx.rootDir);
   709→  }
   710→
   711→  // Get inbox items with triage status (oldest first to encourage triage)
   712→  // AC: @session-start-inbox-triage ac-inbox-untriaged-def
   713→  const allInboxSummaries: InboxSummary[] = inboxItems
   714→    .sort(
   715→      (a, b) =>
   716→        new Date(a.created_at).getTime() - new Date(b.created_at).getTime(),
   717→    )
   718→    .map((item) => {
   719→      const triageInfo = triageByInboxRef.get(item._ulid);
   720→      return {
   721→        ref: item._ulid.slice(0, 8),
   722→        text: item.text,
   723→        created_at: item.created_at,
   724→        tags: item.tags,
   725→        added_by: item.added_by || null,
   726→        triaged: !!triageInfo,
   727→        triage_action: triageInfo?.action ?? null,
   728→      };
   729→    });
   730→
   731→  // AC: @session-start-inbox-triage ac-inbox-stat-line, ac-inbox-all-triaged
   732→  const inboxStats: InboxStats = {
   733→    total: allInboxSummaries.length,
   734→    untriaged: allInboxSummaries.filter((i) => !i.triaged).length,
   735→    deferred: allInboxSummaries.filter((i) => i.triage_action === "defer")
   736→      .length,
   737→    triaged: allInboxSummaries.filter((i) => i.triaged).length,
   738→  };
   739→
   740→  // JSON always gets full list with triage status; human display filters in formatSessionContext
   741→  const inboxSummaries: InboxSummary[] = allInboxSummaries;
   742→
   743→  // Load session context (focus, threads, questions)
   744→  const sessionContext = await loadSessionContext(ctx);
   745→
   746→  // Build task ref resolver for activity timeline: maps slug/ULID to short ref
   747→  // This allows commits with Task: @task-slug trailers to match completed tasks
   748→  const taskRefResolver = new Map<string, string>();
   749→  for (const task of allTasks) {
   750→    if (task.status !== "completed") continue;
   751→    const shortRef = index.shortUlid(task._ulid);
   752→    // Map each slug to the short ref
   753→    for (const slug of task.slugs) {
   754→      taskRefResolver.set(slug, shortRef);
   755→    }
   756→    // Also map the full ULID and short ULID to itself
   757→    taskRefResolver.set(task._ulid, shortRef);
   758→    taskRefResolver.set(shortRef, shortRef);
   759→  }
   760→
   761→  // Build unified activity timeline
   762→  // AC: @session-start-activity-timeline ac-activity-merge
   763→  // AC: @cmd-session-start ac-primer-default, ac-full-sections
   764→  // Primer: 10 items; Full: 20 items
   765→  const activityLimit = options.full ? 20 : 10;
   766→  const activityTimeline = buildActivityTimeline(
   767→    recentlyCompleted,
   768→    recentCommits,
   769→    taskRefResolver,
   770→  ).slice(0, activityLimit);
   771→
   772→  return {
   773→    generated_at: new Date().toISOString(),
   774→    branch,
   775→    context: sessionContext,
   776→    active_tasks: activeTasks,
   777→    pending_review_tasks: pendingReviewTasks,
   778→    recent_notes: recentNotes,
   779→    active_todos: activeTodos,
   780→    ready_tasks: readyTasks,
   781→    blocked_tasks: blockedTasks,
   782→    recently_completed: recentlyCompleted,
   783→    recent_commits: recentCommits,
   784→    activity_timeline: activityTimeline,
   785→    working_tree: workingTree,
   786→    inbox_items: inboxSummaries,
   787→    inbox_stats: inboxStats,
