function formatSessionContext(
  ctx: SessionContext,
  options: SessionOptions,
): void {
  const isFull = !!options.full;

  // AC: @cmd-session-start ac-slug-display, ac-slug-fallback
  // Display ref as @slug when available, @short-ulid when not
  const displayRef = (task: { ref: string; slug?: string | null }) =>
    task.slug ? `@${task.slug}` : `@${task.ref}`;

  // Header
  console.log(`\n${sessionHeaders.title}`);
  const age = formatRelativeTime(new Date(ctx.generated_at));
  if (ctx.branch) {
    console.log(chalk.gray(`Branch: ${ctx.branch} | Generated: ${age}`));
  } else {
    console.log(chalk.gray(`Generated: ${age}`));
  }

  // Stats summary
  const pendingReviewNote =
    ctx.stats.pending_review > 0
      ? `${ctx.stats.pending_review} awaiting review, `
      : "";
  const inboxNote =
    ctx.stats.inbox_items > 0 ? ` | Inbox: ${ctx.stats.inbox_items}` : "";
  console.log(
    chalk.gray(
      `Tasks: ${ctx.stats.in_progress} active, ${pendingReviewNote}${ctx.stats.ready} ready, ` +
        `${ctx.stats.blocked} blocked, ${ctx.stats.completed}/${ctx.stats.total_tasks} completed${inboxNote}`,
    ),
  );

  // Session context section (focus, threads, questions)
  if (
    ctx.context &&
    (ctx.context.focus ||
      ctx.context.threads.length > 0 ||
      ctx.context.open_questions.length > 0)
  ) {
    console.log("\n--- Session Context ---");

    if (ctx.context.focus) {
      console.log(`  ${chalk.cyan("Focus:")} ${ctx.context.focus}`);
    }

    if (ctx.context.threads.length > 0) {
      console.log(`  ${chalk.cyan("Active Threads:")}`);
      for (const thread of ctx.context.threads) {
        console.log(`    - ${thread}`);
      }
    }

    if (ctx.context.open_questions.length > 0) {
      console.log(`  ${chalk.cyan("Open Questions:")}`);
      for (const question of ctx.context.open_questions) {
        console.log(`    - ${question}`);
      }
    }
  }

  // ── Section ordering per AC: @cmd-session-start ac-section-order ──
  // active tasks → pending review → blocked → ready → recent activity → inbox → working tree → quick commands
  // AC: @cmd-session-start ac-empty-skip — empty sections omitted entirely

  // ── Active tasks section ──
  // AC: @cmd-session-start ac-active-detail, ac-needs-work-indicator
  if (ctx.active_tasks.length > 0) {
    console.log(`\n${sessionHeaders.activeWork}`);

    // Collect notes relevant to active tasks for inline display
    const activeTaskNotes = ctx.recent_notes.filter(
      (n) =>
        n.task_status === "in_progress" || n.task_status === "needs_work",
    );

    for (const task of ctx.active_tasks) {
      const started = task.started_at
        ? chalk.gray(
            ` (started ${formatRelativeTime(new Date(task.started_at))})`,
          )
        : "";
      const priority =
        task.priority <= 2
          ? chalk.red(`P${task.priority}`)
          : chalk.gray(`P${task.priority}`);

      // AC: @cmd-session-start ac-needs-work-indicator
      const statusLabel =
        task.status === "needs_work"
          ? chalk.red("[needs_work]")
          : chalk.blue("[in_progress]");

      console.log(
        `  ${statusLabel} ${priority} ${displayRef(task)} ${task.title}${started}`,
      );

      // AC: @cmd-session-start ac-active-detail — show description
      if (task.description) {
        console.log(chalk.gray(`    ${task.description}`));
      }

      // AC: @cmd-session-start ac-active-detail — show recent notes inline
      const taskNotes = activeTaskNotes.filter(
        (n) => n.task_ref === task.ref,
      );
      if (taskNotes.length > 0) {
        const latestNote = taskNotes[0]; // already sorted most recent first
        const noteAge = formatRelativeTime(new Date(latestNote.created_at));
        const author = latestNote.author
          ? chalk.gray(` by ${latestNote.author}`)
          : "";
        console.log(`    ${chalk.yellow("Note")} ${chalk.gray(`(${noteAge}${author})`)}`);

        let content = latestNote.content.trim();
        if (!isFull && content.length > 200) {
          content = `${content.slice(0, 200).trim()}...`;
        }
        const lines = content.split("\n");
        const maxLines = isFull ? lines.length : 3;
        for (const line of lines.slice(0, maxLines)) {
          console.log(`      ${chalk.white(line)}`);
        }
        if (!isFull && lines.length > maxLines) {
          console.log(
            chalk.gray(
              `      ... (${lines.length - maxLines} more lines)`,
            ),
          );
        }
      }
    }
  }

  // ── Awaiting review section ──
  // AC: @cmd-session-start ac-review-detail
  if (ctx.pending_review_tasks.length > 0) {
    console.log(`\n${sessionHeaders.awaitingReview}`);

    const reviewNotes = ctx.recent_notes.filter(
      (n) => n.task_status === "pending_review",
    );

    for (const task of ctx.pending_review_tasks) {
      const priority =
        task.priority <= 2
          ? chalk.red(`P${task.priority}`)
          : chalk.gray(`P${task.priority}`);
      console.log(
        `  ${chalk.yellow("[pending_review]")} ${priority} ${displayRef(task)} ${task.title}`,
      );

      // AC: @cmd-session-start ac-review-detail — show recent notes
      const taskNotes = reviewNotes.filter((n) => n.task_ref === task.ref);
      if (taskNotes.length > 0) {
        const latestNote = taskNotes[0];
        const noteAge = formatRelativeTime(new Date(latestNote.created_at));
        const author = latestNote.author
          ? chalk.gray(` by ${latestNote.author}`)
          : "";
        console.log(`    ${chalk.yellow("Note")} ${chalk.gray(`(${noteAge}${author})`)}`);

        let content = latestNote.content.trim();
        if (!isFull && content.length > 200) {
          content = `${content.slice(0, 200).trim()}...`;
        }
        const lines = content.split("\n");
        const maxLines = isFull ? lines.length : 3;
        for (const line of lines.slice(0, maxLines)) {
          console.log(`      ${chalk.white(line)}`);
        }
        if (!isFull && lines.length > maxLines) {
          console.log(
            chalk.gray(
              `      ... (${lines.length - maxLines} more lines)`,
            ),
          );
        }
      }
    }
  }

  // ── Blocked tasks section ──
  if (ctx.blocked_tasks.length > 0) {
    console.log(`\n${sessionHeaders.blocked}`);
    for (const task of ctx.blocked_tasks) {
      const unlocks =
        task.unlocks > 0 ? chalk.green(` unlocks ${task.unlocks}`) : "";
      console.log(
        `  ${chalk.red("[blocked]")} ${displayRef(task)} ${task.title}${unlocks}`,
      );
      if (task.blocked_by.length > 0) {
        console.log(chalk.gray(`    Blockers: ${task.blocked_by.join(", ")}`));
      }
      if (task.unmet_deps.length > 0) {
        console.log(
          chalk.gray(`    Waiting on: ${task.unmet_deps.join(", ")}`),
        );
      }
    }
  }

  // ── Ready tasks section ──
  if (ctx.ready_tasks.length > 0) {
    console.log(`\n${sessionHeaders.readyTasks}`);
    for (const task of ctx.ready_tasks) {
      const priority =
        task.priority <= 2
          ? chalk.red(`P${task.priority}`)
          : chalk.gray(`P${task.priority}`);
      const tags =
        task.tags.length > 0 ? chalk.cyan(` #${task.tags.join(" #")}`) : "";
      const unlocks =
        task.unlocks > 0 ? chalk.green(` unlocks ${task.unlocks}`) : "";
      console.log(
        `  ${priority} ${displayRef(task)} ${task.title}${unlocks}${tags}`,
      );
    }
  }

  // ── Recent Activity timeline ──
  // AC: @session-start-activity-timeline ac-activity-merge
  if (ctx.activity_timeline.length > 0) {
    console.log(`\n${sessionHeaders.recentActivity}`);
    const observationPromotedTasks: string[] = [];
    for (const item of ctx.activity_timeline) {
      // AC: @cmd-session-start ac-relative-time-human
      const itemAge = formatRelativeTime(new Date(item.date));
      if (item.type === "task_completion") {
        let reason = "";
        if (item.task.closed_reason) {
          const maxLen = isFull ? 120 : 60;
          const truncated =
            item.task.closed_reason.length > maxLen
              ? `${item.task.closed_reason.slice(0, maxLen).trim()}...`
              : item.task.closed_reason;
          reason = chalk.gray(` - ${truncated}`);
        }
        // AC: @cmd-session-start ac-slug-display
        const taskDisplay = item.task.slug
          ? `@${item.task.slug}`
          : `@${item.task.ref}`;
        console.log(
          `  ${chalk.green("[completed]")} ${taskDisplay} ${item.task.title} ${chalk.gray(`(${itemAge})`)}${reason}`,
        );
        if (item.task.origin === "observation_promotion") {
          observationPromotedTasks.push(taskDisplay);
        }
      } else if (item.type === "commit") {
        console.log(
          `  ${chalk.yellow(item.commit.hash)} ${item.commit.message} ${chalk.gray(`(${itemAge}, ${item.commit.author})`)}`,
        );
      } else if (item.type === "linked_commit") {
        // AC: @session-start-activity-timeline ac-activity-dedup, ac-activity-trailer-link
        const taskDisplay = item.task.slug
          ? `@${item.task.slug}`
          : `@${item.task.ref}`;
        console.log(
          `  ${chalk.yellow(item.commit.hash)} ${item.commit.message} ${chalk.gray(`(${itemAge}, ${item.commit.author})`)} ${chalk.green(`→ ${taskDisplay} ${item.task.title}`)}`,
        );
        if (item.task.origin === "observation_promotion") {
          observationPromotedTasks.push(taskDisplay);
        }
      }
    }

    // Show reminder about resolving observations
    if (observationPromotedTasks.length > 0) {
      console.log(
        chalk.yellow(
          `\n  ℹ Consider resolving linked observations: ${observationPromotedTasks.join(", ")}`,
        ),
      );
      console.log(
        chalk.gray(`    Run: kspec meta observations --pending-resolution`),
      );
    }
  }

  // ── Inbox section ──
  // AC: @session-start-inbox-triage ac-inbox-stat-line, ac-inbox-full-list, ac-inbox-all-triaged
  if (ctx.inbox_stats.total > 0) {
    console.log(`\n${sessionHeaders.inbox}`);
    // Stat line always shown (primer and full)
    const statParts = [
      `${ctx.inbox_stats.untriaged} untriaged`,
      `${ctx.inbox_stats.deferred} deferred`,
      `${ctx.inbox_stats.total} total`,
    ];
    console.log(`  ${statParts.join(" | ")}`);

    // AC: @cmd-session-start ac-full-sections, @session-start-inbox-triage ac-inbox-full-list
    // Full mode: list untriaged items (up to 20)
    // AC: @cmd-session-start ac-slug-fallback — inbox uses @short-ulid
    const untriagedItems = ctx.inbox_items
      .filter((i) => !i.triaged)
      .slice(0, 20);
    if (isFull && untriagedItems.length > 0) {
      console.log("");
      for (const item of untriagedItems) {
        const itemAge = formatRelativeTime(new Date(item.created_at));
        const author = item.added_by ? ` by ${item.added_by}` : "";
        const tags =
          item.tags.length > 0
            ? chalk.cyan(` [${item.tags.join(", ")}]`)
            : "";
        console.log(
          `  ${chalk.magenta(`@${item.ref}`)} ${chalk.gray(`(${itemAge}${author})`)}${tags}`,
        );
        console.log(`    ${item.text}`);
      }
    }
    if (ctx.inbox_stats.untriaged > 0) {
      console.log(`  ${hints.inboxTriage}`);
    }
  }

  // ── Working tree section ──
  // AC: @cmd-session-start ac-dirty-tree-only — only shown when dirty
  if (ctx.working_tree && !ctx.working_tree.clean) {
    console.log(`\n${sessionHeaders.workingTree}`);

    if (ctx.working_tree.staged.length > 0) {
      console.log(chalk.green("  Staged:"));
      for (const file of ctx.working_tree.staged) {
        console.log(
          `    ${chalk.green(file.status[0].toUpperCase())} ${file.path}`,
        );
      }
    }

    if (ctx.working_tree.unstaged.length > 0) {
      console.log(chalk.red("  Modified:"));
      for (const file of ctx.working_tree.unstaged) {
        console.log(
          `    ${chalk.red(file.status[0].toUpperCase())} ${file.path}`,
        );
      }
    }

    if (ctx.working_tree.untracked.length > 0) {
      console.log(chalk.gray("  Untracked:"));
      const untrackedLimit = isFull
        ? ctx.working_tree.untracked.length
        : 5;
      for (const filePath of ctx.working_tree.untracked.slice(
        0,
        untrackedLimit,
      )) {
        console.log(`    ${chalk.gray("?")} ${filePath}`);
      }
      if (!isFull && ctx.working_tree.untracked.length > untrackedLimit) {
        console.log(
          chalk.gray(
            `    ... and ${ctx.working_tree.untracked.length - untrackedLimit} more`,
          ),
        );
      }
    }
  }

  // ── Quick Commands section ──
  const quickCommands: string[] = [];

  if (ctx.active_tasks.length > 0) {
    const ref = displayRef(ctx.active_tasks[0]);
    quickCommands.push(
      `kspec task note ${ref} "Progress..."  ${chalk.gray("# document work")}`,
    );
    quickCommands.push(
      `kspec task complete ${ref} --reason "..."  ${chalk.gray("# finish task")}`,
    );
  } else if (ctx.ready_tasks.length > 0) {
    const ref = displayRef(ctx.ready_tasks[0]);
    quickCommands.push(
      `kspec task start ${ref}  ${chalk.gray("# begin work")}`,
    );
  }

  if (ctx.inbox_stats.untriaged > 0) {
    quickCommands.push(
      `kspec triage inbox  ${chalk.gray("# triage untriaged inbox items")}`,
    );
  }

  if (ctx.working_tree && !ctx.working_tree.clean) {
    quickCommands.push(
      `git add . && git commit -m "..."  ${chalk.gray("# commit changes")}`,
    );
  }

  if (quickCommands.length > 0) {
    console.log(`\n${sessionHeaders.quickCommands}`);
    for (const hint of quickCommands) {
      console.log(`  ${hint}`);
    }
  }

  console.log(""); // Final newline

/**
 * Tests for formatSessionContext() rewrite — primer/full modes
 *
 * AC: @cmd-session-start ac-primer-default
 * AC: @cmd-session-start ac-full-sections
 * AC: @cmd-session-start ac-brief-alias
 * AC: @cmd-session-start ac-section-order
 * AC: @cmd-session-start ac-empty-skip
 * AC: @cmd-session-start ac-slug-display
 * AC: @cmd-session-start ac-slug-fallback
 * AC: @cmd-session-start ac-relative-time-human
 * AC: @cmd-session-start ac-iso-time-json
 * AC: @cmd-session-start ac-dirty-tree-only
 * AC: @cmd-session-start ac-active-detail
 * AC: @cmd-session-start ac-needs-work-indicator
 * AC: @cmd-session-start ac-review-detail
 * AC: @cmd-session-start ac-notes-starvation
 * AC: @cmd-session-start ac-json-raw-preserved
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import {
  kspec,
  kspecJson,
  setupTempFixtures,
  cleanupTempDir,
  initGitRepo,
  git,
} from '../helpers/cli';

interface ActiveTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  description: string | null;
  status: 'in_progress' | 'needs_work' | 'pending_review';
  started_at: string | null;
  priority: number;
  spec_ref: string | null;
  note_count: number;
  last_note_at: string | null;
  todo_count: number;
  incomplete_todos: number;
}

interface ReadyTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  description: string | null;
  priority: number;
  spec_ref: string | null;
  tags: string[];
  unlocks: number;
}

interface BlockedTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  description: string | null;
  blocked_by: string[];
  unmet_deps: string[];
  unlocks: number;
}

interface CompletedTaskSummary {
  ref: string;
  slug: string | null;
  title: string;
  completed_at: string;
  closed_reason: string | null;
}

interface CommitSummary {
  hash: string;
  full_hash: string;
  date: string;
  message: string;
  author: string;
  task_refs: string[];
}

interface ActivityItem {
  type: 'task_completion' | 'commit' | 'linked_commit';
  date: string;
  commit?: CommitSummary;
  task?: CompletedTaskSummary;
}

interface NoteSummary {
  task_ref: string;
  task_title: string;
  task_status: 'in_progress' | 'pending_review' | 'needs_work' | 'completed';
  note_ulid: string;
  created_at: string;
  author: string | null;
  content: string;
}

interface InboxStats {
  total: number;
  untriaged: number;
  deferred: number;
  triaged: number;
}

interface SessionContext {
  generated_at: string;
  branch: string | null;
  active_tasks: ActiveTaskSummary[];
  pending_review_tasks: ActiveTaskSummary[];
  ready_tasks: ReadyTaskSummary[];
  blocked_tasks: BlockedTaskSummary[];
  recently_completed: CompletedTaskSummary[];
  recent_commits: CommitSummary[];
  activity_timeline: ActivityItem[];
  recent_notes: NoteSummary[];
  inbox_items: Array<{ ref: string; triaged: boolean }>;
  inbox_stats: InboxStats;
  stats: {
    total_tasks: number;
    in_progress: number;
    needs_work: number;
    pending_review: number;
    ready: number;
    blocked: number;
    completed: number;
    inbox_items: number;
  };
  working_tree: {
    clean: boolean;
    staged: Array<{ status: string; path: string }>;
    unstaged: Array<{ status: string; path: string }>;
    untracked: string[];
  } | null;
}

describe('session start format rewrite', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
    initGitRepo(tempDir);
    writeFileSync(join(tempDir, 'README.md'), '# Test\n');
    git('add .', tempDir);
    git('commit -m "initial commit"', tempDir);
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  // AC: @cmd-session-start ac-primer-default
  describe('primer mode (default)', () => {
    it('should limit ready tasks to 5 in primer mode', { timeout: 30000 }, () => {
      // Create 8 ready tasks
      for (let i = 1; i <= 8; i++) {
        kspec(`task add --title "Ready ${i}" --slug ready-${i}`, tempDir);
      }

      const session = kspecJson<SessionContext>('session start --json', tempDir);
      expect(session.ready_tasks.length).toBe(5);
    });

    it('should limit activity timeline to 10 items in primer mode', { timeout: 30000 }, () => {
      // Create and complete 12 tasks to get 12 activity items
      for (let i = 1; i <= 12; i++) {
        kspec(`task add --title "Task ${i}" --slug task-${i}`, tempDir);
        kspec(`task start @task-${i}`, tempDir);
        kspec(`task submit @task-${i}`, tempDir);
        kspec(`task complete @task-${i} --reason "Done"`, tempDir);
      }

      const session = kspecJson<SessionContext>('session start --json', tempDir);
      expect(session.activity_timeline.length).toBeLessThanOrEqual(10);
    });

    it('should show inbox stat line only in primer mode', () => {
      // Fixture already has inbox items
      const result = kspec('session start', tempDir);

      // Should show stat line
      if (result.stdout.includes('untriaged')) {
        expect(result.stdout).toContain('untriaged');
        expect(result.stdout).toContain('total');
      }
    });
  });

  // AC: @cmd-session-start ac-full-sections
  describe('full mode', () => {
    it('should show all ready tasks in full mode', { timeout: 30000 }, () => {
      // Create 8 ready tasks (fixture already has some)
      for (let i = 1; i <= 8; i++) {
        kspec(`task add --title "Ready ${i}" --slug ready-${i}`, tempDir);
      }

      const primerSession = kspecJson<SessionContext>('session start --json', tempDir);
      const fullSession = kspecJson<SessionContext>('session start --full --json', tempDir);

      // Primer caps at 5, full shows all
      expect(primerSession.ready_tasks.length).toBe(5);
      expect(fullSession.ready_tasks.length).toBeGreaterThan(5);
    });

    it('should show up to 20 activity items in full mode', { timeout: 30000 }, () => {
      // Create and complete 12 tasks
