  task_title: string;
  task_status: "in_progress" | "pending_review" | "needs_work" | "completed";
  note_ulid: string;
  created_at: string;
  author: string | null;
  content: string;
}

export interface TodoSummary {
  task_ref: string;
  task_title: string;
  id: number;
