346→    slug: task.slugs.length > 0 ? task.slugs[0] : null,
347→    title: task.title,
348→    description: task.description || null,
349→    status: task.status as "in_progress" | "needs_work" | "pending_review",
350→    started_at: task.started_at || null,
351→    priority: task.priority,
352→    spec_ref: task.spec_ref || null,
353→    note_count: task.notes.length,
354→    last_note_at: lastNote ? lastNote.created_at : null,
355→    todo_count: task.todos.length,
