420→function collectRecentNotes(
421→  tasks: LoadedTask[],
422→  index: ReferenceIndex,
423→  options: { limit: number; since: Date | null },
424→): NoteSummary[] {
425→  const allNotes: NoteSummary[] = [];
426→
427→  for (const task of tasks) {
428→    // Only include notes from in_progress, pending_review, or completed tasks
429→    const taskStatus = task.status as "in_progress" | "pending_review" | "needs_work" | "completed";
430→    if (!["in_progress", "pending_review", "needs_work", "completed"].includes(taskStatus)) {
431→      continue;
432→    }
433→
434→    for (const note of task.notes) {
435→      const noteDate = new Date(note.created_at);
436→
437→      // Filter by since date if provided
438→      if (options.since && noteDate < options.since) {
439→        continue;
440→      }
441→
442→      // Filter out superseded notes
443→      if (isNoteSuperseded(note, task.notes)) {
444→        continue;
445→      }
446→
447→      allNotes.push({
448→        task_ref: index.shortUlid(task._ulid),
449→        task_title: task.title,
450→        task_status: taskStatus,
451→        note_ulid: note._ulid.slice(0, 8),
452→        created_at: note.created_at,
453→        author: note.author || null,
454→        content: note.content,
455→      });
456→    }
457→  }
458→
459→  // Sort by date descending, take limit
460→  return allNotes
461→    .sort(
462→      (a, b) =>
463→        new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
464→    )
465→    .slice(0, options.limit);
466→}
