/**
 * Tests for session start activity timeline
 *
 * AC: @session-start-activity-timeline ac-activity-merge
 * AC: @session-start-activity-timeline ac-activity-trailer-link
 * AC: @session-start-activity-timeline ac-activity-sort
 * AC: @session-start-activity-timeline ac-activity-dedup
 * AC: @session-start-activity-timeline ac-activity-no-git
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { kspec, kspecJson, setupTempFixtures, cleanupTempDir, initGitRepo, git } from '../helpers/cli';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';

interface CommitSummary {
  hash: string;
  full_hash: string;
  date: string;
  message: string;
  author: string;
  task_refs: string[];
}

interface CompletedTaskSummary {
  ref: string;
  title: string;
  completed_at: string;
  closed_reason: string | null;
}

interface ActivityItem {
  type: 'task_completion' | 'commit' | 'linked_commit';
  date: string;
  commit?: CommitSummary;
  task?: CompletedTaskSummary;
}

interface SessionContext {
  recently_completed: CompletedTaskSummary[];
  recent_commits: CommitSummary[];
  activity_timeline: ActivityItem[];
}

describe('session start activity timeline', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
    initGitRepo(tempDir);
    // Initial commit so git log works
    writeFileSync(join(tempDir, 'README.md'), '# Test\n');
    git('add .', tempDir);
    git('commit -m "initial commit"', tempDir);
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  // AC: @session-start-activity-timeline ac-activity-merge
  describe('activity merge (ac-activity-merge)', () => {
    it('should include both completed tasks and commits in a single timeline', () => {
      // Create and complete a task
      kspec('task add --title "Feature alpha" --slug task-alpha', tempDir);
      kspec('task start @task-alpha', tempDir);
      kspec('task submit @task-alpha', tempDir);
      kspec('task complete @task-alpha --reason "Shipped alpha"', tempDir);

      // Create a git commit (not linked to any task)
      writeFileSync(join(tempDir, 'feature.ts'), 'export const x = 1;\n');
      git('add feature.ts', tempDir);
      git('commit -m "feat: add feature file"', tempDir);

      const session = kspecJson<SessionContext>('session start --json', tempDir);

      // activity_timeline should contain entries from both sources
      expect(session.activity_timeline.length).toBeGreaterThanOrEqual(2);

      const taskEntries = session.activity_timeline.filter(
        (i) => i.type === 'task_completion',
      );
      const commitEntries = session.activity_timeline.filter(
        (i) => i.type === 'commit',
      );

      expect(taskEntries.length).toBeGreaterThanOrEqual(1);
      expect(commitEntries.length).toBeGreaterThanOrEqual(1);
    });

    it('should show Recent Activity header in human output instead of separate sections', () => {
      // Create and complete a task
      kspec('task add --title "Feature beta" --slug task-beta', tempDir);
      kspec('task start @task-beta', tempDir);
      kspec('task submit @task-beta', tempDir);
      kspec('task complete @task-beta --reason "Shipped beta"', tempDir);

      // Create a git commit
      writeFileSync(join(tempDir, 'beta.ts'), 'export const beta = 1;\n');
      git('add beta.ts', tempDir);
      git('commit -m "feat: add beta"', tempDir);

      const result = kspec('session start', tempDir);

      // Should have unified "Recent Activity" section
      expect(result.stdout).toContain('Recent Activity');

      // Should NOT have separate "Recent Commits" section
      // (the section header text is "--- Recent Commits ---")
      expect(result.stdout).not.toContain('Recent Commits ---');
    });

    it('should preserve raw recently_completed and recent_commits arrays in JSON', () => {
      // Create and complete a task
      kspec('task add --title "Raw check" --slug task-raw', tempDir);
      kspec('task start @task-raw', tempDir);
      kspec('task submit @task-raw', tempDir);
      kspec('task complete @task-raw --reason "Done"', tempDir);

      // Create a commit
      writeFileSync(join(tempDir, 'raw.ts'), 'export const raw = 1;\n');
      git('add raw.ts', tempDir);
      git('commit -m "feat: raw check"', tempDir);

      const session = kspecJson<SessionContext>('session start --json', tempDir);

      // Raw arrays should still be present
      expect(session.recently_completed).toBeDefined();
      expect(session.recently_completed.length).toBeGreaterThanOrEqual(1);
      expect(session.recent_commits).toBeDefined();
      expect(session.recent_commits.length).toBeGreaterThanOrEqual(1);

      // Plus the unified timeline
      expect(session.activity_timeline).toBeDefined();
      expect(session.activity_timeline.length).toBeGreaterThanOrEqual(2);
    });
  });

  // AC: @session-start-activity-timeline ac-activity-trailer-link
  describe('trailer linking (ac-activity-trailer-link)', () => {
    it('should show linked task info when commit has Task: @slug trailer', () => {
      // Create and complete a task
      kspec('task add --title "Linked feature" --slug task-linked', tempDir);
      kspec('task start @task-linked', tempDir);
      kspec('task submit @task-linked', tempDir);
      kspec('task complete @task-linked --reason "All done"', tempDir);

      // Create a commit with a Task: trailer using the task slug (convention)
      writeFileSync(join(tempDir, 'linked.ts'), 'export const linked = 1;\n');
      git('add linked.ts', tempDir);
      git('commit -m "feat: implement linked feature" -m "Task: @task-linked"', tempDir);

      const session = kspecJson<SessionContext>('session start --json', tempDir);

      // Should have a linked_commit entry
      const linkedEntries = session.activity_timeline.filter(
        (i) => i.type === 'linked_commit',
      );
      expect(linkedEntries.length).toBe(1);
      expect(linkedEntries[0].commit!.task_refs).toContain('task-linked');
      expect(linkedEntries[0].task!.title).toBe('Linked feature');
    });

    it('should show linked task info in human output', () => {
      kspec('task add --title "Human linked" --slug task-human-linked', tempDir);
      kspec('task start @task-human-linked', tempDir);
      kspec('task submit @task-human-linked', tempDir);
      kspec('task complete @task-human-linked --reason "Done"', tempDir);

      writeFileSync(join(tempDir, 'hl.ts'), 'export const hl = 1;\n');
      git('add hl.ts', tempDir);
      git('commit -m "feat: human linked feature" -m "Task: @task-human-linked"', tempDir);

      const result = kspec('session start', tempDir);

      // Human output should show commit → task link
      expect(result.stdout).toContain('Human linked');
      expect(result.stdout).toContain('human linked feature');
    });

    it('should include task_refs in commit summary JSON', () => {
      writeFileSync(join(tempDir, 'refcheck.ts'), 'export const rc = 1;\n');
      git('add refcheck.ts', tempDir);
      git('commit -m "feat: ref check commit" -m "Task: @task-ref-check"', tempDir);

      const session = kspecJson<SessionContext>('session start --json', tempDir);

      const commit = session.recent_commits.find((c) =>
        c.message.includes('ref check commit'),
      );
      expect(commit).toBeDefined();
      expect(commit!.task_refs).toContain('task-ref-check');
    });
  });

  // AC: @session-start-activity-timeline ac-activity-sort
  describe('chronological sort (ac-activity-sort)', () => {
    it('should sort timeline items most recent first', { timeout: 15000 }, () => {
      // Create a task completed "earlier"
      kspec('task add --title "Earlier task" --slug task-earlier', tempDir);
      kspec('task start @task-earlier', tempDir);
      kspec('task submit @task-earlier', tempDir);
      kspec('task complete @task-earlier --reason "Done first"', tempDir);

      // Create a commit with a future date to guarantee different timestamps
      // Git --date flag sets the author date, ensuring it sorts after the task completion
      writeFileSync(join(tempDir, 'later.ts'), 'export const later = 1;\n');
      git('add later.ts', tempDir);
      git('commit -m "feat: later commit" --date="2099-01-01T00:00:00Z"', tempDir);

      const session = kspecJson<SessionContext>('session start --json', tempDir);

      // Should have at least 2 items (task + commit)
      expect(session.activity_timeline.length).toBeGreaterThanOrEqual(2);

      // Verify sorted most recent first
      for (let i = 1; i < session.activity_timeline.length; i++) {
        const prevDate = new Date(session.activity_timeline[i - 1].date).getTime();
        const currDate = new Date(session.activity_timeline[i].date).getTime();
        expect(prevDate).toBeGreaterThanOrEqual(currDate);
      }

      // The commit with future date should be first
      expect(session.activity_timeline[0].type).toBe('commit');
      expect(session.activity_timeline[0].commit!.message).toBe('feat: later commit');
    });
  });

  // AC: @session-start-activity-timeline ac-activity-dedup
  describe('deduplication (ac-activity-dedup)', () => {
    it('should show linked commit+task as single combined entry, not two separate entries', () => {
      kspec('task add --title "Dedup task" --slug task-dedup', tempDir);
      kspec('task start @task-dedup', tempDir);
      kspec('task submit @task-dedup', tempDir);
      kspec('task complete @task-dedup --reason "Dedup done"', tempDir);

      writeFileSync(join(tempDir, 'dedup.ts'), 'export const dedup = 1;\n');
      git('add dedup.ts', tempDir);
      git('commit -m "feat: dedup feature" -m "Task: @task-dedup"', tempDir);

      const session = kspecJson<SessionContext>('session start --json', tempDir);

      // Should have exactly one linked_commit entry for this task
      const linkedEntries = session.activity_timeline.filter(
        (i) => i.type === 'linked_commit' && i.task?.title === 'Dedup task',
      );
      expect(linkedEntries.length).toBe(1);

      // The task should NOT appear as a separate task_completion entry
      const taskOnlyEntries = session.activity_timeline.filter(
        (i) => i.type === 'task_completion' && i.task?.title === 'Dedup task',
      );
      expect(taskOnlyEntries.length).toBe(0);

      // The commit should NOT appear as a separate commit entry
      const commitOnlyEntries = session.activity_timeline.filter(
        (i) => i.type === 'commit' && i.commit?.message === 'feat: dedup feature',
      );
      expect(commitOnlyEntries.length).toBe(0);
    });

    it('should show unlinked commit and unlinked task as separate entries', () => {
      // Complete a task (no commit linked)
      kspec('task add --title "Standalone task" --slug task-standalone', tempDir);
      kspec('task start @task-standalone', tempDir);
      kspec('task submit @task-standalone', tempDir);
      kspec('task complete @task-standalone --reason "Done alone"', tempDir);

      // Create unlinked commit
      writeFileSync(join(tempDir, 'standalone.ts'), 'export const x = 1;\n');
      git('add standalone.ts', tempDir);
      git('commit -m "chore: standalone commit"', tempDir);

      const session = kspecJson<SessionContext>('session start --json', tempDir);

      // Each should appear as its own type
      const taskEntries = session.activity_timeline.filter(
        (i) => i.type === 'task_completion' && i.task?.title === 'Standalone task',
      );
      expect(taskEntries.length).toBe(1);

      const commitEntries = session.activity_timeline.filter(
        (i) => i.type === 'commit' && i.commit?.message === 'chore: standalone commit',
      );
      expect(commitEntries.length).toBe(1);
    });
  });

  // AC: @session-start-activity-timeline ac-activity-no-git
  describe('--no-git flag (ac-activity-no-git)', () => {
    it('should only show task completions when --no-git is passed', () => {
      // Create and complete a task
      kspec('task add --title "No-git task" --slug task-no-git', tempDir);
      kspec('task start @task-no-git', tempDir);
      kspec('task submit @task-no-git', tempDir);
      kspec('task complete @task-no-git --reason "Done without git"', tempDir);

      // Create a commit
      writeFileSync(join(tempDir, 'nogit.ts'), 'export const x = 1;\n');
      git('add nogit.ts', tempDir);
      git('commit -m "feat: should not appear"', tempDir);

      const session = kspecJson<SessionContext>('session start --json --no-git', tempDir);

      // Timeline should only contain task_completion entries
      expect(session.activity_timeline.length).toBeGreaterThanOrEqual(1);
      for (const item of session.activity_timeline) {
        expect(item.type).toBe('task_completion');
      }

      // recent_commits should be empty
      expect(session.recent_commits).toHaveLength(0);
    });

    it('should not show commit entries in human output with --no-git', () => {
      kspec('task add --title "Visible task" --slug task-visible', tempDir);
      kspec('task start @task-visible', tempDir);
      kspec('task submit @task-visible', tempDir);
      kspec('task complete @task-visible --reason "Visible"', tempDir);

      writeFileSync(join(tempDir, 'hidden.ts'), 'export const x = 1;\n');
      git('add hidden.ts', tempDir);
      git('commit -m "feat: invisible commit"', tempDir);

      const result = kspec('session start --no-git', tempDir);

      // Task should be visible
      expect(result.stdout).toContain('Visible task');
      // Commit should not be visible
      expect(result.stdout).not.toContain('invisible commit');
    });
  });
});

 * Build a unified activity timeline from completed tasks and git commits.
 *
 * - Commits with Task: @slug trailers are matched to completed tasks and shown
 *   as combined "linked_commit" entries (AC: ac-activity-trailer-link, ac-activity-dedup)
 * - Unlinked commits appear as standalone "commit" entries
 * - Tasks not linked to any commit appear as standalone "task_completion" entries
 * - All items sorted most recent first (AC: ac-activity-sort)
 *
 * @param completedTasks - Completed task summaries
 * @param commits - Recent commit summaries (with task_refs parsed from trailers)
 * @param taskRefResolver - Maps a trailer ref (slug or ULID prefix) to a completed task's ref (short ULID)
 */
function buildActivityTimeline(
  completedTasks: CompletedTaskSummary[],
  commits: CommitSummary[],
  taskRefResolver: Map<string, string>,
): ActivityItem[] {
  const items: ActivityItem[] = [];

  // Build lookup from short ULID ref to CompletedTaskSummary
  const taskByRef = new Map<string, CompletedTaskSummary>();
  for (const task of completedTasks) {
    taskByRef.set(task.ref, task);
  }

  // Track which tasks have been linked to a commit (for dedup)
  const linkedTaskRefs = new Set<string>();

  for (const commit of commits) {
    if (commit.task_refs.length > 0) {
      let linkedTask: CompletedTaskSummary | undefined;
      for (const trailerRef of commit.task_refs) {
        // Resolve the trailer ref (slug or ULID) to the short ULID ref
        const resolvedRef = taskRefResolver.get(trailerRef);
        if (resolvedRef) {
          linkedTask = taskByRef.get(resolvedRef);
        }
        // Also try direct match on short ULID ref
        if (!linkedTask) {
          linkedTask = taskByRef.get(trailerRef);
        }
        if (linkedTask) {
          linkedTaskRefs.add(linkedTask.ref);
          // Use the later of commit date and task completion date for sort accuracy
          const commitTime = new Date(commit.date).getTime();
          const taskTime = new Date(linkedTask.completed_at).getTime();
          const laterDate =
            taskTime > commitTime ? linkedTask.completed_at : commit.date;
          items.push({
            type: "linked_commit",
            date: laterDate,
            commit,
            task: linkedTask,
          });
          break; // One linked entry per commit
        }
      }
      if (!linkedTask) {
        // Task ref in trailer but no matching completed task found
        items.push({ type: "commit", date: commit.date, commit });
      }
    } else {
      items.push({ type: "commit", date: commit.date, commit });
    }
  }

  // Add task completions not already linked to a commit
  for (const task of completedTasks) {
    if (!linkedTaskRefs.has(task.ref)) {
      items.push({
        type: "task_completion",
        date: task.completed_at,
        task,
      });
    }
  }

  // AC: @session-start-activity-timeline ac-activity-sort
  // Sort most recent first
  items.sort(
    (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime(),
  );

  return items;
}

/**
 * Gather session context data
 */
export async function gatherSessionContext(
  ctx: KspecContext,
  options: SessionOptions,
): Promise<SessionContext> {
  const limit = parseInt(options.limit || "10", 10);
  const sinceDate = options.since ? parseTimeSpec(options.since) : null;
  const showGit = options.git !== false; // default true

  // Load all data
  const allTasks = await loadAllTasks(ctx);
  const items = await loadAllItems(ctx);
  const inboxItems = await loadInboxItems(ctx);
  const triageRecords = await loadTriageRecords(ctx);
  const index = new ReferenceIndex(allTasks, items);

  // AC: @session-start-inbox-triage ac-inbox-untriaged-def
  // Build lookup: inbox ULID → triage record (most recent if multiple)
  const triageByInboxRef = new Map<string, { action?: string }>();
  for (const record of triageRecords) {
    triageByInboxRef.set(record.inbox_ref, { action: record.action });
  }

  // Compute stats
  const stats: SessionStats = {
    total_tasks: allTasks.length,
    in_progress: allTasks.filter((t) => t.status === "in_progress").length,
    needs_work: allTasks.filter((t) => t.status === "needs_work").length,
    pending_review: allTasks.filter((t) => t.status === "pending_review")
      .length,
    ready: getReadyTasks(allTasks).length,
    blocked: allTasks.filter((t) => t.status === "blocked").length,
    completed: allTasks.filter((t) => t.status === "completed").length,
    inbox_items: inboxItems.length,
  };

  // Get active tasks (in_progress + needs_work, optionally filtered to automation-eligible only)
  // AC: @cli-ralph ac-16
  const activeTasks = allTasks
    .filter((t) => t.status === "in_progress" || t.status === "needs_work")
    .filter((t) => !options.eligible || t.automation === "eligible")
    .sort((a, b) => a.priority - b.priority)
    .slice(0, options.full ? undefined : limit)
    .map((t) => toActiveTaskSummary(t, index));

  // Get pending review tasks
  const pendingReviewTasks = allTasks
    .filter((t) => t.status === "pending_review")
    .sort((a, b) => a.priority - b.priority)
    .slice(0, options.full ? undefined : limit)
    .map((t) => toActiveTaskSummary(t, index));

  // Get recent notes from active, pending_review, and recently completed tasks
  // AC: @cmd-session-start ac-1, ac-2
  // Collect notes per-status first to prevent one status from starving others
  const noteLimitPerStatus = options.full ? limit : Math.ceil(limit / 3);

  const inProgressNotes = collectRecentNotes(
    allTasks.filter((t) => t.status === "in_progress" || t.status === "needs_work"),
    index,
    { limit: noteLimitPerStatus, since: sinceDate },
  );

  const pendingReviewNotes = collectRecentNotes(
    allTasks.filter((t) => t.status === "pending_review"),
    index,
    { limit: noteLimitPerStatus, since: sinceDate },
  );

  const recentlyCompletedForNotes = allTasks
    .filter((t) => t.status === "completed" && t.completed_at)
    .sort((a, b) => {
      const aDate = new Date(a.completed_at || 0);
      const bDate = new Date(b.completed_at || 0);
      return bDate.getTime() - aDate.getTime();
    })
    .slice(0, 5); // Last 3-5 completed tasks per AC-2

  const completedNotes = collectRecentNotes(
    recentlyCompletedForNotes,
    index,
    { limit: noteLimitPerStatus, since: sinceDate },
  );

  // Combine notes from all statuses, preserving representation from each
  const recentNotes = [...inProgressNotes, ...pendingReviewNotes, ...completedNotes]
    .sort(
      (a, b) =>
        new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
    );

  // Get incomplete todos from active tasks
  const activeTodos = collectIncompleteTodos(
    allTasks.filter((t) => t.status === "in_progress" || t.status === "needs_work"),
    index,
    { limit: options.full ? limit * 2 : limit },
  );

  // Compute reverse dependency map for "unlocks N" annotations
  const unlocksMap = computeUnlocksMap(allTasks, index);

  // AC: @cmd-session-start ac-primer-default, ac-full-sections
  // Primer: top 5 ready tasks; Full: all ready tasks
  // Respect --limit as upper bound when provided
  const readyLimit = options.full ? undefined : Math.min(limit, 5);
  const readyTasks = getReadyTasks(allTasks)
    .filter((t) => !options.eligible || t.automation === "eligible")
    .slice(0, readyLimit)
    .map((t) => toReadyTaskSummary(t, index, unlocksMap));

  // Get blocked tasks
  const blockedTasks = allTasks
    .filter((t) => t.status === "blocked")
    .slice(0, options.full ? undefined : limit)
    .map((t) => toBlockedTaskSummary(t, allTasks, index, unlocksMap));

  // Get recently completed tasks
  const recentlyCompleted = allTasks
    .filter((t) => {
      if (t.status !== "completed" || !t.completed_at) return false;
      const completedDate = new Date(t.completed_at);
      if (sinceDate && completedDate < sinceDate) return false;
      return true;
    })
    .sort((a, b) => {
      // Sort by completed_at descending (most recent first)
      const aDate = new Date(a.completed_at || 0);
      const bDate = new Date(b.completed_at || 0);
      return bDate.getTime() - aDate.getTime();
    })
    .slice(0, options.full ? undefined : limit)
    .map((t) => toCompletedTaskSummary(t, index));

  // Get git info
  let branch: string | null = null;
  let recentCommits: CommitSummary[] = [];
  let workingTree: GitWorkingTree | null = null;

  if (showGit && isGitRepo(ctx.rootDir)) {
    branch = getCurrentBranch(ctx.rootDir);

    const commits = getRecentCommits({
      limit: options.full ? limit * 2 : limit,
      since: sinceDate || undefined,
      cwd: ctx.rootDir,
    });

    recentCommits = commits.map((c) => ({
      hash: c.hash,
      full_hash: c.fullHash,
      date: c.date.toISOString(),
      message: c.message,
      author: c.author,
      task_refs: c.taskRefs,
    }));

    workingTree = getWorkingTreeStatus(ctx.rootDir);
  }

  // Get inbox items with triage status (oldest first to encourage triage)
  // AC: @session-start-inbox-triage ac-inbox-untriaged-def
  const allInboxSummaries: InboxSummary[] = inboxItems
    .sort(
      (a, b) =>
        new Date(a.created_at).getTime() - new Date(b.created_at).getTime(),
    )
    .map((item) => {
      const triageInfo = triageByInboxRef.get(item._ulid);
      return {
        ref: item._ulid.slice(0, 8),
        text: item.text,
        created_at: item.created_at,
        tags: item.tags,
        added_by: item.added_by || null,
        triaged: !!triageInfo,
        triage_action: triageInfo?.action ?? null,
      };
    });

  // AC: @session-start-inbox-triage ac-inbox-stat-line, ac-inbox-all-triaged
  const inboxStats: InboxStats = {
    total: allInboxSummaries.length,
    untriaged: allInboxSummaries.filter((i) => !i.triaged).length,
    deferred: allInboxSummaries.filter((i) => i.triage_action === "defer")
      .length,
    triaged: allInboxSummaries.filter((i) => i.triaged).length,
  };

  // JSON always gets full list with triage status; human display filters in formatSessionContext
  const inboxSummaries: InboxSummary[] = allInboxSummaries;

  // Load session context (focus, threads, questions)
  const sessionContext = await loadSessionContext(ctx);

  // Build task ref resolver for activity timeline: maps slug/ULID to short ref
  // This allows commits with Task: @task-slug trailers to match completed tasks
  const taskRefResolver = new Map<string, string>();
  for (const task of allTasks) {
    if (task.status !== "completed") continue;
    const shortRef = index.shortUlid(task._ulid);
    // Map each slug to the short ref
    for (const slug of task.slugs) {
      taskRefResolver.set(slug, shortRef);
    }
    // Also map the full ULID and short ULID to itself
    taskRefResolver.set(task._ulid, shortRef);
    taskRefResolver.set(shortRef, shortRef);
  }

  // Build unified activity timeline
  // AC: @session-start-activity-timeline ac-activity-merge
  // AC: @cmd-session-start ac-primer-default, ac-full-sections
  // Primer: 10 items; Full: 20 items
  // Respect --limit as upper bound when provided
  const activityLimit = options.full ? Math.min(limit * 2, 20) : Math.min(limit, 10);
  const activityTimeline = buildActivityTimeline(
    recentlyCompleted,
    recentCommits,
    taskRefResolver,
  ).slice(0, activityLimit);

  // AC: @cmd-session-start ac-full-sections — observations section (full mode only)
  let observations: ObservationSummary[] = [];
  if (options.full) {
    const metaCtx = await loadMetaContext(ctx);
    observations = metaCtx.observations
      .filter((o) => !o.resolved)
      .sort(
        (a, b) =>
          new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
      )
      .map((o) => ({
        ref: o._ulid.slice(0, 8),
        type: o.type,
        content: o.content,
        created_at: o.created_at,
        author: o.author || null,
        resolved: o.resolved,
        workflow_ref: o.workflow_ref || null,
      }));
  }

  // AC: @session-start-computed-json ac-computed-unlocks
  // Build task_unlocks map: short ULID ref → count of pending dependents
  const taskUnlocks: Record<string, number> = {};
  for (const [taskUlid, count] of unlocksMap) {
    if (count > 0) {
      taskUnlocks[index.shortUlid(taskUlid)] = count;
    }
  }

  // AC: @session-start-computed-json ac-computed-inbox, ac-computed-unlocks, ac-computed-activity
  const computed: SessionContextComputed = {
    inbox_untriaged_count: inboxStats.untriaged,
    inbox_deferred_count: inboxStats.deferred,
    inbox_total: inboxStats.total,
    task_unlocks: taskUnlocks,
    recent_activity: activityTimeline,
  };

  return {
    generated_at: new Date().toISOString(),
    branch,
    context: sessionContext,
    active_tasks: activeTasks,
    pending_review_tasks: pendingReviewTasks,
    recent_notes: recentNotes,
    active_todos: activeTodos,
    ready_tasks: readyTasks,
    blocked_tasks: blockedTasks,
    recently_completed: recentlyCompleted,
    recent_commits: recentCommits,
    activity_timeline: activityTimeline,
    working_tree: workingTree,
    inbox_items: inboxSummaries,
    inbox_stats: inboxStats,
    observations,
    stats,
    computed,
  };
}

// ─── Iteration Stats ─────────────────────────────────────────────────────────

/**
 * Stats for tasks completed/started within a time window.
 * Used by ralph to track task completions per iteration.
 */
export interface IterationStats {
  /** Number of tasks completed since the given time */
  tasks_completed: number;
  /** Number of tasks started since the given time */
  tasks_started: number;
  /** References of completed tasks */
  completed_refs: string[];
}

/**
 * Get iteration stats - tasks completed/started since a given time.
 * AC: @ralph-task-limit ac-detection
 */
export async function getIterationStats(
  ctx: KspecContext,
  since: Date,
): Promise<IterationStats> {
  const allTasks = await loadAllTasks(ctx);

  // Count both completed and pending_review (submitted) tasks toward the limit.
  // Submit means the agent's work is done — it should count the same as complete.
  // AC: @ralph-task-limit ac-detection
  const completedSince = allTasks.filter((t) => {
    if (t.status === "completed" && t.completed_at) {

      return new Date(t.completed_at) >= since;
    }
    if (t.status === "pending_review" && t.submitted_at) {
      return new Date(t.submitted_at) >= since;
    }
    return false;
  });

  const startedSince = allTasks.filter((t) => {
    if (!t.started_at) return false;
    return new Date(t.started_at) >= since;
  });

  // Use first slug or ULID prefix as ref
  const getRef = (t: LoadedTask) =>
    t.slugs.length > 0 ? `@${t.slugs[0]}` : `@${t._ulid.slice(0, 8)}`;

  return {
    tasks_completed: completedSince.length,
    tasks_started: startedSince.length,
    completed_refs: completedSince.map(getRef),
  };
}

// ─── Checkpoint ──────────────────────────────────────────────────────────────

export interface CheckpointOptions {
  force?: boolean;
  /** Set when stop hook is already active (retry after previous block) */
  stopHookActive?: boolean;
}

/** Claude Code hook input for Stop hooks */
export interface StopHookInput {
  session_id?: string;
  transcript_path?: string;
  hook_event_name?: string;
  stop_hook_active?: boolean;
}

/**
 * Perform session checkpoint - check for uncommitted work before ending session.
 *
 * This is designed for use as a Claude Code stop hook. It checks for:
 * - Uncommitted git changes (staged, unstaged, untracked)
 * - Tasks in in_progress status
 * - Incomplete todos on active tasks
 *
 * Returns a structured result indicating whether the session can end cleanly.
 */
export async function performCheckpoint(
  ctx: KspecContext,
  options: CheckpointOptions,
): Promise<CheckpointResult> {
  const issues: CheckpointIssue[] = [];
  const instructions: string[] = [];

  // Load tasks
  const allTasks = await loadAllTasks(ctx);

  // Check for in-progress tasks
  const inProgressTasks = allTasks.filter((t) => t.status === "in_progress");
  for (const task of inProgressTasks) {
    const ref = task.slugs[0]
      ? `@${task.slugs[0]}`
      : `@${task._ulid.slice(0, 8)}`;
    issues.push({
      type: "in_progress_task",
      description: `Task ${ref} is still in progress: ${task.title}`,
      details: {
        ref,
        title: task.title,
        started_at: task.started_at,
      },
    });

    // Check for incomplete todos on this task
    const incompleteTodos = task.todos.filter((t) => !t.done);
    for (const todo of incompleteTodos) {
      issues.push({
        type: "incomplete_todo",
        description: `Incomplete todo on ${ref}: ${todo.text}`,
        details: {
          task_ref: ref,
          todo_id: todo.id,
          text: todo.text,
        },
      });
    }
  }

  // Check for uncommitted git changes
  if (isGitRepo(ctx.rootDir)) {
    const workingTree = getWorkingTreeStatus(ctx.rootDir);
    if (!workingTree.clean) {
      const changeCount =
        workingTree.staged.length +
        workingTree.unstaged.length +
        workingTree.untracked.length;

      issues.push({
        type: "uncommitted_changes",
        description: `${changeCount} uncommitted changes in working tree`,
        details: {
          staged: workingTree.staged.length,
          unstaged: workingTree.unstaged.length,
          untracked: workingTree.untracked.length,
        },
      });
    }
  }

  // Build instructions based on issues
  if (issues.length > 0 && !options.force) {
    instructions.push(
      "If you've been instructed to ignore this message or are working on",
    );
    instructions.push(
      "unrelated things to any in progress tasks then disregard this message,",
    );
    instructions.push("otherwise before ending this session, please:");

    const hasInProgress = issues.some((i) => i.type === "in_progress_task");
    const hasUncommitted = issues.some((i) => i.type === "uncommitted_changes");
    const hasIncompleteTodos = issues.some((i) => i.type === "incomplete_todo");

    let step = 1;

    if (hasInProgress) {
      instructions.push(
        `${step++}. Read in-progress task notes to get full context of the current task status`,
      );
      instructions.push(
        `${step++}. Add notes documenting current state if any context is missing from this session`,
      );
      instructions.push(
        `${step++}. Complete the task if you've completed the objectives and no AC are left uncovered\notherwise leave it in progress for a future session`,
      );
    }

    if (hasIncompleteTodos) {
      instructions.push(
        `${step++}. Complete or acknowledge incomplete todos on active tasks`,
      );
    }

    if (hasUncommitted) {
      instructions.push(
        `${step++}. Commit your changes with a descriptive message`,
      );

      // Add WIP commit guidance if there are in-progress tasks
      if (inProgressTasks.length > 0) {
        const task = inProgressTasks[0];
        const guidance = formatCommitGuidance(task, { wip: true });
        instructions.push("");
        instructions.push("Suggested WIP commit:");
        instructions.push(`  ${guidance.message}`);
        instructions.push("");
        for (const trailer of guidance.trailers) {
          instructions.push(`  ${trailer}`);
        }
      }
    }

    instructions.push("");
    instructions.push("Use: kspec task @task to get current task state");
    instructions.push(
      'Use: kspec task note @task "Progress notes..." to document state',
    );
    instructions.push(
      'Use: kspec task complete @task --reason "Summary" if task is done',
    );
  }

  // Allow stop if:
  // - No issues found
  // - --force flag passed
  // - This is a retry (stop_hook_active = true from previous block)
  const isRetry = options.stopHookActive === true;
  const ok = issues.length === 0 || options.force === true || isRetry;

  let message: string;
  if (isRetry && issues.length > 0) {
    message = `[kspec] Session checkpoint: ${issues.length} issue(s) acknowledged - allowing stop`;
  } else if (ok) {
    message = "[kspec] Session checkpoint passed - ready to end session";
  } else {
    message = `[kspec] Session checkpoint: ${issues.length} issue(s) need attention`;
  }

  return {
    ok,
    message,
    issues,
    instructions,
  };
}

// ─── Output Formatting ───────────────────────────────────────────────────────

function formatCheckpointResult(result: CheckpointResult): void {
  if (result.ok) {
    console.log(chalk.green(result.message));
  } else {
    console.log(chalk.yellow(result.message));
    console.log("");

    for (const issue of result.issues) {
      const icon =
        issue.type === "uncommitted_changes"
          ? chalk.yellow("⚠")
          : issue.type === "in_progress_task"
            ? chalk.blue("●")
            : chalk.gray("○");
      console.log(`  ${icon} ${issue.description}`);
    }

    if (result.instructions.length > 0) {
      console.log("");
      for (const instruction of result.instructions) {
        console.log(chalk.gray(instruction));
      }
    }
  }
}

function formatSessionContext(
  ctx: SessionContext,
  options: SessionOptions,
